question.answer:
def pair_labels(pairs):
    labels = []
    for site, count in pairs:
        labels.append(f"{site}: {count}")
    return labels


def total_count(pairs):
    total = 0
    for _, count in pairs:
        total += count
    return total


def strip_footer(lines):
    *body, footer = lines
    return body


def middle_char(code):
    _, middle, _ = code
    return middle

