question.answer:
def summarise(readings):
    return min(readings), max(readings), sum(readings) / len(readings)


def swapped(left, right):
    left, right = right, left
    return left, right


def split_head(readings):
    head, *tail = readings
    return head, tail


def split_ends(readings):
    first, *middle, last = readings
    return first, middle, last


def unpack_record(record):
    (site, channel), value = record
    return site, channel, value


def one_tuple():
    x = 5,
    return x
